// @domain: domains
//! #4766 — the spine log as tool calls: read only its end, join each call's start and end.
//! No crate dependencies beyond serde_json, so athena-gen's own tests compile it directly.
//! Generated by athena-gen from its template — DO NOT EDIT; change the generator.

use serde_json::Value;
use std::io::{Read, Seek, SeekFrom};

/// How much of the log's end one read takes. 4 MB holds about the last hour of calls.
#[allow(dead_code)]
pub const TAIL_BYTES: u64 = 4 * 1024 * 1024;

/// The log's last `max` bytes as text, without the partial first line. A missing or
/// unreadable log is an error (unmeasured), never an empty list that reads as "no work".
pub fn tail(path: &str, max: u64) -> Result<String, String> {
    let mut f = std::fs::File::open(path).map_err(|e| format!("spine log {path} unreadable: {e}"))?;
    let size = f.metadata().map_err(|e| format!("spine log {path}: {e}"))?.len();
    let start = size.saturating_sub(max);
    f.seek(SeekFrom::Start(start)).map_err(|e| format!("spine log {path}: {e}"))?;
    let mut buf = Vec::with_capacity((size - start) as usize);
    f.take(max).read_to_end(&mut buf).map_err(|e| format!("spine log {path}: {e}"))?;
    let text = String::from_utf8_lossy(&buf).into_owned();
    if start == 0 {
        return Ok(text);
    }
    Ok(text.split_once('\n').map(|(_, rest)| rest.to_string()).unwrap_or_default())
}

/// One tool call, joined from its start and end.
#[derive(Debug, Clone, PartialEq)]
pub struct Call {
    pub id: String,
    pub what: String,
    pub role: String,
    pub tool: String,
    pub ts: String,
    pub session: String,
    pub card: String,
    /// done, failed, running or stopped
    pub phase: String,
}

fn s(v: &Value, k: &str) -> String {
    match v.get(k) {
        Some(Value::String(x)) => x.clone(),
        Some(Value::Number(n)) => n.to_string(),
        _ => String::new(),
    }
}

/// The calls in `text`, newest first. Only `agent.action` lines make rows.
pub fn calls(text: &str) -> Vec<Call> {
    let mut started: Vec<Call> = Vec::new();
    let mut ended: std::collections::HashMap<String, String> = std::collections::HashMap::new();
    let mut turn_ends: Vec<(String, String, String)> = Vec::new(); // role, session, ts
    for line in text.lines() {
        let Ok(v) = serde_json::from_str::<Value>(line) else { continue };
        match s(&v, "event").as_str() {
            "agent.action" => {
                let (id, tool) = (s(&v, "call_id"), s(&v, "tool"));
                if id.is_empty() || tool.is_empty() {
                    continue;
                }
                if s(&v, "phase") == "ended" {
                    let outcome = s(&v, "outcome");
                    ended.insert(id, if outcome.is_empty() { "ok".into() } else { outcome });
                } else {
                    let digest = s(&v, "digest");
                    started.push(Call {
                        what: if digest.is_empty() { tool.clone() } else { digest },
                        id, tool,
                        role: s(&v, "role"), ts: s(&v, "timestamp"),
                        session: s(&v, "session_id"), card: s(&v, "card_id"),
                        phase: String::new(),
                    });
                }
            }
            "agent.turn.ended" => {
                let session = s(&v, "session_id");
                if !session.is_empty() {
                    turn_ends.push((s(&v, "role"), session, s(&v, "timestamp")));
                }
            }
            _ => {}
        }
    }
    for c in started.iter_mut() {
        c.phase = match ended.get(&c.id) {
            Some(o) if o == "error" => "failed".into(),
            Some(_) => "done".into(),
            None if turn_ends.iter().any(|(r, sess, ts)| *r == c.role && *sess == c.session && *ts >= c.ts) => "stopped".into(),
            None => "running".into(),
        };
    }
    started.reverse();
    started
}

